corrected_code:
const express = require('express');
const { Queue } = require('bullmq');

const app = express();
app.use(express.json());

const transcodeQueue = new Queue('video-transcode', {
  connection: { host: 'redis.internal', port: 6379 }
});

app.patch('/api/queues/video-transcode/jobs/:jobId/priority', async (req, res) => {
  if (!req.user || !req.user.accountId) {
    return res.status(401).json({ error: 'Authentication required' });
  }

  const { jobId } = req.params;
  const { priority } = req.body;

  const job = await transcodeQueue.getJob(jobId);
  if (!job) {
    return res.status(404).json({ error: 'Job not found' });
  }

  // Ensure job belongs to caller's account
  if (job.data.accountId !== req.user.accountId) {
    return res.status(403).json({ error: 'Forbidden: unauthorized job priority update' });
  }

  await job.changePriority({ priority: Number(priority) });
  res.json({ success: true, jobId, newPriority: priority });
});

app.listen(8009);
